	}
})

frappe.ui.form.on('Sales Invoice Item', {
	refresh(frm) {
		// your code here
	}
})

frappe.ui.form.on("Item", {
	last_purchase_rate(frm) {
		fill_empty_packing_purchase_rates(frm);
	},
	custom_default_purchase_rate(frm) {
		fill_empty_packing_purchase_rates(frm);
	},
});

frappe.ui.form.on("Retail Packing Detail", {
	conversion_factor(frm, cdt, cdn) {
		set_default_packing_purchase_rate(frm, cdt, cdn);
	},
	custom_retail_packing_detail_add(frm, cdt, cdn) {
		set_default_packing_purchase_rate(frm, cdt, cdn);
	},
});

function get_packing_base_purchase_rate(frm) {
	return flt(frm.doc.custom_default_purchase_rate || frm.doc.last_purchase_rate);
}

function set_default_packing_purchase_rate(frm, cdt, cdn) {
	const row = locals[cdt][cdn];
	if (flt(row.purchase_rate)) return;

	const base_rate = get_packing_base_purchase_rate(frm);
	if (!base_rate) return;

	frappe.model.set_value(
		cdt,
		cdn,
		"purchase_rate",
		base_rate * flt(row.conversion_factor || 1)
	);
}

function fill_empty_packing_purchase_rates(frm) {
	(frm.doc.custom_retail_packing_detail || []).forEach((row) => {
		if (!flt(row.purchase_rate)) {
			set_default_packing_purchase_rate(frm, row.doctype, row.name);
		}
	});
}

(function () {
	frappe.ui.form.on("Item", {
		refresh(frm) { set_margin_amount(frm); },
		standard_rate(frm) { set_margin_amount(frm); },
		custom_sales_net_rate(frm) { set_margin_amount(frm); },
		custom_sales_rate_entry(frm) { set_margin_amount(frm); },
		custom_b2b(frm) { set_margin_amount(frm); },
		last_purchase_rate(frm) { set_margin_amount(frm); },
		valuation_rate(frm) { set_margin_amount(frm); },
		custom_default_purchase_rate(frm) { set_margin_amount(frm); },
		custom_average_purchase_rate(frm) { set_margin_amount(frm); },
		custom_purchase_net_rate(frm) { set_margin_amount(frm); },
		custom_purchase_rate_entry(frm) { set_margin_amount(frm); },
	});

	function set_margin_amount(frm) {
		const selling_net = get_selling_net_rate(frm);
		const cost_net = get_cost_net_rate(frm);
		frm.set_value("custom_margin", flt(selling_net - cost_net, 2));
	}

	function get_selling_net_rate(frm) {
		if (has_entered_value(frm.doc.custom_sales_rate_entry)) {
			return flt(frm.doc.custom_sales_net_rate);
		}
		return flt(frm.doc.standard_rate || frm.doc.custom_b2b);
	}

	function get_cost_net_rate(frm) {
		if (has_entered_value(frm.doc.custom_purchase_rate_entry)) {
			return flt(frm.doc.custom_purchase_net_rate);
		}
		return flt(
			frm.doc.custom_average_purchase_rate
			|| frm.doc.custom_default_purchase_rate
			|| frm.doc.last_purchase_rate
			|| frm.doc.valuation_rate
		);
	}

	function has_entered_value(value) {
		return value !== undefined && value !== null && value !== "";
	}
})();

(function () {
	frappe.ui.form.on("Item", {
		refresh(frm) { set_margin_percent(frm); },
		standard_rate(frm) { set_margin_percent(frm); },
		custom_sales_net_rate(frm) { set_margin_percent(frm); },
		custom_sales_rate_entry(frm) { set_margin_percent(frm); },
		custom_b2b(frm) { set_margin_percent(frm); },
		last_purchase_rate(frm) { set_margin_percent(frm); },
		valuation_rate(frm) { set_margin_percent(frm); },
		custom_default_purchase_rate(frm) { set_margin_percent(frm); },
		custom_average_purchase_rate(frm) { set_margin_percent(frm); },
		custom_purchase_net_rate(frm) { set_margin_percent(frm); },
		custom_purchase_rate_entry(frm) { set_margin_percent(frm); },
	});

	function set_margin_percent(frm) {
		const selling_net = get_selling_net_rate(frm);
		const margin = selling_net - get_cost_net_rate(frm);
		frm.set_value("custom_margin_", selling_net ? flt((margin / selling_net) * 100, 3) : 0);
	}

	function get_selling_net_rate(frm) {
		if (has_entered_value(frm.doc.custom_sales_rate_entry)) {
			return flt(frm.doc.custom_sales_net_rate);
		}
		return flt(frm.doc.standard_rate || frm.doc.custom_b2b);
	}

	function get_cost_net_rate(frm) {
		if (has_entered_value(frm.doc.custom_purchase_rate_entry)) {
			return flt(frm.doc.custom_purchase_net_rate);
		}
		return flt(
			frm.doc.custom_average_purchase_rate
			|| frm.doc.custom_default_purchase_rate
			|| frm.doc.last_purchase_rate
			|| frm.doc.valuation_rate
		);
	}

	function has_entered_value(value) {
		return value !== undefined && value !== null && value !== "";
	}
})();

frappe.ui.form.on('Item', {

    custom_scale_item: function(frm) {

        if (frm.doc.custom_scale_item) {

            if (!frm.doc.custom_barcode) {

                let prefix = "21";
                let rand = Math.floor(10000 + Math.random() * 90000);

                frm.set_value(
                    'custom_barcode',
                    prefix + rand
                );
            }
        }
    }

});

frappe.ui.form.on('Item', {
    custom_warranty: function(frm) {
        if (!frm.doc.custom_warranty) {
            frm.set_value('custom_in_months', null);
        }
    }
});

frappe.ui.form.on("Item", {
    item_name(frm) {
        queue_last_purchase_rate_lookup(frm);
    },

    refresh(frm) {
        if (frm.is_new() && frm.doc.item_name) {
            queue_last_purchase_rate_lookup(frm);
        }
    }
});

function queue_last_purchase_rate_lookup(frm) {
    if (!frm.is_new()) {
        return;
    }

    clearTimeout(frm._last_purchase_rate_lookup);

    const item_name = (frm.doc.item_name || "").trim();
    if (!item_name) {
        frm._last_purchase_rate_source = null;
        frm.dashboard.clear_headline();
        frm.set_value("last_purchase_rate", 0);
        return;
    }

    frm._last_purchase_rate_lookup = setTimeout(() => {
        set_last_purchase_rate_from_same_item_name(frm, item_name);
    }, 350);
}

function set_last_purchase_rate_from_same_item_name(frm, requested_item_name) {
    if (!frm.is_new() || !requested_item_name) {
        return;
    }

    frappe.db.get_list("Item", {
        fields: ["name", "item_name", "last_purchase_rate", "standard_rate"],
        filters: {
            item_name: requested_item_name,
            disabled: 0
        },
        order_by: "modified desc",
        limit: 1
    }).then((items) => {
        const current_item_name = (frm.doc.item_name || "").trim();
        if (current_item_name !== requested_item_name) {
            return;
        }

        if (!items.length || !flt(items[0].last_purchase_rate)) {
            frm._last_purchase_rate_source = null;
            frm.dashboard.clear_headline();
            frm.set_value("last_purchase_rate", 0);
            return;
        }

        frm.set_value("last_purchase_rate", items[0].last_purchase_rate);

        if (frm._last_purchase_rate_source !== items[0].name) {
            frm._last_purchase_rate_source = items[0].name;
            frm.dashboard.clear_headline();
            frm.dashboard.set_headline(__("Last purchase rate fetched from existing Item {0}", [items[0].name]));
        }
    });
}

frappe.ui.form.on("Item", {
    validate(frm) {
        remove_empty_barcode_rows(frm);
    },
    before_save(frm) {
        remove_empty_barcode_rows(frm);
    }
});

function remove_empty_barcode_rows(frm) {
    if (!Array.isArray(frm.doc.barcodes) || !frm.doc.barcodes.length) return;

    let removed = false;
    for (let i = frm.doc.barcodes.length - 1; i >= 0; i--) {
        const row = frm.doc.barcodes[i];
        if (row.barcode) continue;

        if (row.doctype && row.name) {
            frappe.model.clear_doc(row.doctype, row.name);
        }
        frm.doc.barcodes.splice(i, 1);
        removed = true;
    }

    if (removed) {
        frm.refresh_field("barcodes");
    }
}

frappe.ui.form.on("Purchase Order Item", {
	qty(frm, cdt, cdn) {
		set_balance_qty(cdt, cdn);
	},
	received_qty(frm, cdt, cdn) {
		set_balance_qty(cdt, cdn);
	}
});

function set_balance_qty(cdt, cdn) {
	const row = locals[cdt][cdn];
	frappe.model.set_value(cdt, cdn, "balance_qty", flt(row.qty) - flt(row.received_qty));
}
